<script setup>
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { useAuthStore } from '@/stores/auth'
import AppIcon from '@/components/AppIcon.vue'
const router=useRouter(),auth=useAuthStore()
const modo=ref('login'),email=ref(''),password=ref(''),error=ref(''),mensaje=ref(''),procesando=ref(false)
async function enviar(){error.value='';mensaje.value='';procesando.value=true;try{if(modo.value==='login'){await auth.iniciarSesion(email.value.trim(),password.value);await router.replace('/')}else{const activo=await auth.registrar(email.value.trim(),password.value);if(activo)await router.replace('/');else{mensaje.value='Revisa tu correo para confirmar la cuenta.';modo.value='login'}}}catch(e){error.value=e.message}finally{procesando.value=false}}
async function entrarDemo(){await auth.iniciarSesion('','');await router.replace('/')}
</script>
<template>
  <main class="login-shell"><section class="login-art"><div><div class="brand-in-login"><AppIcon name="ticket" :size="35"/> Control de Bingo</div><h1>Una forma más simple de organizar tus cartones.</h1><p style="max-width:460px;margin-top:25px">Administra grupos, asigna rangos y consulta la distribución desde una sola aplicación.</p></div><div class="sample-watermark" style="background:#ffffff14;color:#e3eeff;border-color:#ffffff26;max-width:400px"><AppIcon name="shield" :size="18" style="vertical-align:middle;margin-right:8px"/> Demostración académica · Sin pagos reales</div></section>
  <section class="login-form-side"><div class="login-card"><div class="metric-icon blue" style="margin-bottom:20px"><AppIcon name="lock" :size="25"/></div><h2>{{auth.configurado?'Bienvenido de nuevo':'Explora la demostración'}}</h2><p>{{auth.configurado?'Ingresa con tu cuenta de Supabase.':'No necesitas configurar ningún servicio para probar la interfaz.'}}</p><template v-if="auth.configurado"><div class="segmented" style="margin:25px 0"><button type="button" :class="{active:modo==='login'}" @click="modo='login'">Iniciar sesión</button><button type="button" :class="{active:modo==='registro'}" @click="modo='registro'">Crear cuenta</button></div><form @submit.prevent="enviar"><div class="field"><label for="email">Correo electrónico</label><input id="email" v-model="email" type="email" autocomplete="email" required placeholder="correo@ejemplo.com"/></div><div class="field"><label for="password">Contraseña</label><input id="password" v-model="password" type="password" required minlength="6" :autocomplete="modo==='login'?'current-password':'new-password'" placeholder="••••••••"/></div><button type="submit" class="primary-btn full-width" :disabled="procesando" style="margin-top:12px">{{procesando?'Procesando...':modo==='login'?'Ingresar':'Crear cuenta'}}</button></form></template><button v-else class="primary-btn full-width" style="margin-top:32px" @click="entrarDemo">Entrar a la demostración <AppIcon name="arrow" :size="18"/></button><div v-if="error" role="alert" class="notice error"><AppIcon name="alert"/>{{error}}</div><div v-if="mensaje" role="status" class="notice success">{{mensaje}}</div><p style="margin-top:25px;font-size:11px">Los datos de demostración se guardan solo en este navegador si Supabase no está configurado.</p></div></section></main>
</template>
